import boto3
from botocore.exceptions import ClientError

def extract_document_layout(file_path: str) -> dict:
    client = boto3.client('textract')
    with open(file_path, 'rb') as document:
        image_bytes = document.read()
    try:
        response = client.analyze_document(
            Document={'Bytes': image_bytes},
            FeatureTypes=['TABLES', 'FORMS', 'LAYOUT']
        )
        blocks = response.get('Blocks', [])
        result = {
            'pages': [],
            'tables': [],
            'key_values': [],
            'lines': []
        }
        page_blocks = [b for b in blocks if b['BlockType'] == 'PAGE']
        for page in page_blocks:
            page_num = page.get('Page', 1)
            page_result = {
                'page_number': page_num,
                'text_blocks': [],
                'tables': [],
                'key_values': []
            }
            child_ids = page.get('Relationships', [{}])[0].get('Ids', []) if page.get('Relationships') else []
            for block in blocks:
                if block.get('Id') in child_ids:
                    if block['BlockType'] == 'LINE':
                        page_result['text_blocks'].append({
                            'text': block.get('Text', ''),
                            'confidence': block.get('Confidence', 0),
                            'geometry': block.get('Geometry', {})
                        })
                    elif block['BlockType'] == 'TABLE':
                        table_cells = []
                        for rel in block.get('Relationships', []):
                            if rel['Type'] == 'CHILD':
                                for cell_id in rel['Ids']:
                                    cell_block = next((b for b in blocks if b['Id'] == cell_id), None)
                                    if cell_block and cell_block['BlockType'] == 'CELL':
                                        table_cells.append({
                                            'text': cell_block.get('Text', ''),
                                            'row_index': cell_block.get('RowIndex', 0),
                                            'column_index': cell_block.get('ColumnIndex', 0)
                                        })
                        page_result['tables'].append({
                            'cells': table_cells,
                            'confidence': block.get('Confidence', 0)
                        })
                    elif block['BlockType'] == 'KEY_VALUE_SET':
                        if block.get('EntityTypes', []) and 'KEY' in block['EntityTypes']:
                            key_text = ''
                            value_text = ''
                            for rel in block.get('Relationships', []):
                                if rel['Type'] == 'CHILD':
                                    for child_id in rel['Ids']:
                                        child_block = next((b for b in blocks if b['Id'] == child_id), None)
                                        if child_block and child_block['BlockType'] == 'WORD':
                                            key_text += child_block.get('Text', '') + ' '
                            for value_block in blocks:
                                if value_block.get('BlockType') == 'KEY_VALUE_SET' and 'VALUE' in value_block.get('EntityTypes', []):
                                    for rel in value_block.get('Relationships', []):
                                        if rel['Type'] == 'VALUE':
                                            if block['Id'] in rel.get('Ids', []):
                                                for child_rel in value_block.get('Relationships', []):
                                                    if child_rel['Type'] == 'CHILD':
                                                        for child_id in child_rel['Ids']:
                                                            child_block = next((b for b in blocks if b['Id'] == child_id), None)
                                                            if child_block and child_block['BlockType'] == 'WORD':
                                                                value_text += child_block.get('Text', '') + ' '
                            page_result['key_values'].append({
                                'key': key_text.strip(),
                                'value': value_text.strip(),
                                'confidence': block.get('Confidence', 0)
                            })
            result['pages'].append(page_result)
        for block in blocks:
            if block['BlockType'] == 'LINE':
                result['lines'].append({
                    'text': block.get('Text', ''),
                    'confidence': block.get('Confidence', 0)
                })
        return result
    except ClientError as e:
        raise Exception(f"AWS Textract error: {e.response['Error']['Message']}")
